package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class WholeFractionProductsTest {
 @Test public void everyWholeProductUsesDisplayedNumbers(){int count=0;Checker checker=new Checker();for(int w=0;w<=9;w++)for(int d=2;d<=12;d++)for(int n=1;n<d;n++)for(int k=1;k<=12;k++)for(boolean reverse:new boolean[]{false,true}){Question q=WholeFractionProducts.make(w==0?"fracMulInt":"fracMixedMul",w,n,d,k,reverse);q.answers=new String[]{"999"};q.expression="poison";int expected=(w*d+n)*k;assertTrue(checker.check(q,List.of(),List.of(expected+"/"+d)).correct());assertEquals(Checker.Status.WRONG_ANSWER,checker.check(q,List.of(),List.of((expected+1)+"/"+d)).status);assertEquals(1,FractionInput.errorPart(q,(expected+1)+"/"+d));if(java.math.BigInteger.valueOf(expected).gcd(java.math.BigInteger.valueOf(d)).intValue()==1)assertEquals(2,FractionInput.errorPart(q,expected+"/"+(d+1)));assertArrayEquals(new double[]{w,n,d,k,reverse?1:0},q.diagram.values,0);count++;}assertEquals(15840,count);}
 @Test public void yearFiveSuppliesFreshPicturesAndBlankHelp(){for(String id:List.of("fracMulInt","fracMixedMul")){var limits=GlobalCurriculum.limits("england-primary-2021-v1",id,5);assertTrue(WholeFractionProducts.selected(id,limits));Generator g=new Generator(new Random(179));List<String> recent=new ArrayList<>();boolean forward=false,backward=false;for(int i=0;i<100;i++){Question q=g.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var p=WholeFractionProducts.givens(q);assertNotNull(p);assertEquals("wholeFractionProductGiven",q.diagram.type);forward|=p.left.denominator!=1;backward|=p.left.denominator==1;var help=HelpPlan.forQuestion(q);assertFalse(help.canTransfer());assertEquals(id.equals("fracMulInt")?9:11,help.size());assertTrue(help.restore(null,q.id).entries.stream().allMatch(String::isEmpty));assertEquals("fraction-product-relations-v1",q.studyGuide.teachingVersion);}assertTrue(forward&&backward);}assertFalse(WholeFractionProducts.selected("fracMixedMul",GlobalCurriculum.limits("us-ccss-2010-v1","fracMixedMul",5)));}
 @Test public void representationRulesAndPublicPartLocalization(){Question q=WholeFractionProducts.make("fracMulInt",0,2,3,3,false);q.answers=new String[]{"poison"};Checker c=new Checker();assertTrue(c.check(q,List.of(),List.of("6/3")).correct());assertTrue(c.check(q,List.of(),List.of("2/1")).correct());assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("2")).status);q.kind="reduced";assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("6/3")).status);assertTrue(c.check(q,List.of(),List.of("2/1")).correct());q.answerFormat="decimal";q.kind="number";assertTrue(c.check(q,List.of(),List.of("2.0")).correct());assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),Arrays.asList((String)null)).status);assertEquals(0,WholeFractionProducts.errorPart(q,"99/97"));assertEquals(2,WholeFractionProducts.errorPart(q,"6/4"));assertFalse(WholeFractionProducts.supports(new Question("fracMixedMul","1 1/2 × 2 1/3","","")));}
 @Test public void invalidScopeAndOldNonWholeSupplyRemainSeparate(){for(String prompt:List.of("1/0 × 2","3/2 × 2","2 × 3","1/2 ÷ 3","-1/2 × 3"))assertFalse(WholeFractionProducts.supports(new Question("fracMulInt",prompt,"","")));for(String id:List.of("fracMulInt","fracMixedMul")){Question q=FractionProducts.create(Catalog.get(id),new Random(9));assertEquals("fraction-product-relations-v1",q.studyGuide.teachingVersion);assertFalse(q.studyGuide.transfer);}try{WholeFractionProducts.make("fracMulInt",1,1,2,2,false);fail();}catch(IllegalArgumentException expected){}}
}
